const items = $input.all();
const rawInput = items[0]?.json?.body || items[0]?.json || {};

if (rawInput.topic === undefined || rawInput.topic === null) {
  throw new Error('Validation Error: Missing required field "topic".');
}

if (typeof rawInput.topic !== 'string') {
  throw new Error('Validation Error: "topic" must be a string.');
}

const topic = rawInput.topic.trim();
if (topic.length < 3 || topic.length > 250) {
  throw new Error(`Validation Error: "topic" length must be between 3 and 250 characters (received ${topic.length}).`);
}

let country = 'in';
if (rawInput.country !== undefined && rawInput.country !== null) {
  if (typeof rawInput.country !== 'string') {
    throw new Error('Validation Error: "country" must be a 2-letter ISO country code string.');
  }
  const cleanCountry = rawInput.country.trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(cleanCountry)) {
    throw new Error(`Validation Error: "country" must be a valid 2-letter ISO code (e.g. "in", "us"). Received: "${rawInput.country}".`);
  }
  country = cleanCountry;
}

let language = 'en';
if (rawInput.language !== undefined && rawInput.language !== null) {
  if (typeof rawInput.language !== 'string') {
    throw new Error('Validation Error: "language" must be a valid ISO language code string.');
  }
  const cleanLanguage = rawInput.language.trim().toLowerCase();
  if (!/^[a-z]{2}(-[a-z]{2})?$/.test(cleanLanguage)) {
    throw new Error(`Validation Error: "language" must be a valid language code (e.g. "en", "hi"). Received: "${rawInput.language}".`);
  }
  language = cleanLanguage;
}

// Allowed engines
const validEngineSet = new Set(['google', 'google_scholar', 'google_news', 'google_patents']);
let selectedEngines = ['google'];

if (Array.isArray(rawInput.engines) && rawInput.engines.length > 0) {
  const filtered = [];
  const seen = new Set();
  for (const e of rawInput.engines) {
    if (typeof e === 'string') {
      const norm = e.trim().toLowerCase();
      if (validEngineSet.has(norm) && !seen.has(norm)) {
        seen.add(norm);
        filtered.push(norm);
      }
    }
  }
  if (filtered.length > 0) {
    selectedEngines = filtered;
  }
}

const routeItems = [];
for (const eng of selectedEngines) {
  let queryParams = {
    engine: eng,
    q: topic
  };

  if (eng === 'google') {
    queryParams.gl = country;
    queryParams.hl = language;
    queryParams.num = '10';
  } else if (eng === 'google_scholar') {
    queryParams.hl = language;
    queryParams.num = '10';
  } else if (eng === 'google_news') {
    queryParams.gl = country;
    queryParams.hl = language;
  } else if (eng === 'google_patents') {
    queryParams.num = '10';
  }

  routeItems.push({
    json: {
      topic,
      country,
      language,
      engine: eng,
      selectedEngines,
      queryParams,
      validatedAt: new Date().toISOString()
    }
  });
}

return routeItems;

const allInputs = $input.all();
const validatedContext = $('Validate Input and Route Engines').first()?.json || {};

const topic = validatedContext.topic || 'Unknown Topic';
const country = validatedContext.country || 'in';
const language = validatedContext.language || 'en';
const selectedEngines = validatedContext.selectedEngines || ['google'];

function normalizeUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return null;
  var str = rawUrl.trim();
  if (!/^https?:\/\//i.test(str)) return null;

  var clean = str.split('#')[0];
  var qIndex = clean.indexOf('?');
  if (qIndex === -1) {
    return clean.replace(/\/+$/, '');
  }

  var baseUrl = clean.slice(0, qIndex).replace(/\/+$/, '');
  var queryStr = clean.slice(qIndex + 1);
  var tracking = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid', 'ref', 'ocid', 'mc_cid', 'mc_eid', '_hsenc', '_hsmi'];

  var keptParams = [];
  var pairs = queryStr.split('&');
  for (var i = 0; i < pairs.length; i++) {
    var pair = pairs[i];
    if (!pair) continue;
    var key = pair.split('=')[0].toLowerCase();
    if (tracking.indexOf(key) === -1) {
      keptParams.push(pair);
    }
  }

  return keptParams.length > 0 ? (baseUrl + '?' + keptParams.join('&')) : baseUrl;
}

const engineBreakdown = {
  google: 0,
  google_scholar: 0,
  google_news: 0,
  google_patents: 0
};
const engineErrors = [];
const allExtracted = [];

for (const item of allInputs) {
  const json = item.json || {};

  // Check for error on this engine request
  if (json.error) {
    const failedEngine = json.queryParams?.engine || json.engine || 'unknown';
    engineErrors.push({
      engine: failedEngine,
      message: typeof json.error === 'string' ? json.error : (json.error.message || 'Engine search failed')
    });
    continue;
  }

  const engine = json.search_parameters?.engine || json.engine || 'google';

  if (engine === 'google') {
    const org = json.organic_results || [];
    for (const r of org) {
      allExtracted.push({
        engine: 'google',
        title: (r.title || '').trim(),
        url: r.link,
        normalizedUrl: normalizeUrl(r.link),
        snippet: (r.snippet || '').trim(),
        displayedLink: r.displayed_link || null,
        publicationDate: r.date || null,
        position: r.position || null,
        authors: null,
        publication: r.source || null,
        citationCount: null,
        patentNumber: null,
        inventors: null,
        assignee: null,
        filingDate: null,
        patentPublicationDate: null,
        pdfUrl: null,
        fullDocumentUrl: r.link || null,
        metadata: {
          source: r.source || null,
          displayedLink: r.displayed_link || null,
          favicon: r.favicon || null
        }
      });
      engineBreakdown.google++;
    }
  } else if (engine === 'google_scholar') {
    const org = json.organic_results || [];
    for (const r of org) {
      let authors = null;
      let publication = null;
      if (r.publication_info) {
        if (Array.isArray(r.publication_info.authors)) {
          authors = r.publication_info.authors.map(a => a.name).filter(Boolean);
        }
        publication = r.publication_info.summary || null;
      }

      let citationCount = null;
      if (r.inline_links && r.inline_links.cited_by && typeof r.inline_links.cited_by.total === 'number') {
        citationCount = r.inline_links.cited_by.total;
      }

      let pdfUrl = null;
      if (Array.isArray(r.resources)) {
        const pdfRes = r.resources.find(res => res.file_format === 'PDF' && res.link);
        if (pdfRes) pdfUrl = pdfRes.link;
      }

      allExtracted.push({
        engine: 'google_scholar',
        title: (r.title || '').trim(),
        url: r.link || pdfUrl,
        normalizedUrl: normalizeUrl(r.link || pdfUrl),
        snippet: (r.snippet || '').trim(),
        displayedLink: null,
        publicationDate: null,
        position: r.position || null,
        authors: authors && authors.length > 0 ? authors : null,
        publication: publication,
        citationCount: citationCount,
        patentNumber: null,
        inventors: null,
        assignee: null,
        filingDate: null,
        patentPublicationDate: null,
        pdfUrl: pdfUrl,
        fullDocumentUrl: r.link || null,
        metadata: {
          resultId: r.result_id || null,
          publicationInfo: r.publication_info || null
        }
      });
      engineBreakdown.google_scholar++;
    }
  } else if (engine === 'google_news') {
    const news = json.news_results || [];
    for (const r of news) {
      allExtracted.push({
        engine: 'google_news',
        title: (r.title || '').trim(),
        url: r.link,
        normalizedUrl: normalizeUrl(r.link),
        snippet: (r.snippet || r.title || '').trim(),
        displayedLink: null,
        publicationDate: r.iso_date || r.date || null,
        position: r.position || null,
        authors: Array.isArray(r.source?.authors) ? r.source.authors : null,
        publication: r.source?.name || null,
        citationCount: null,
        patentNumber: null,
        inventors: null,
        assignee: null,
        filingDate: null,
        patentPublicationDate: null,
        pdfUrl: null,
        fullDocumentUrl: r.link || null,
        metadata: {
          source: r.source || null,
          thumbnail: r.thumbnail || null
        }
      });
      engineBreakdown.google_news++;
    }
  } else if (engine === 'google_patents') {
    const org = json.organic_results || [];
    for (const r of org) {
      const patentNumber = r.publication_number || (r.patent_id ? r.patent_id.replace(/^patent\//, '').replace(/\/en$/, '') : null);
      let inventors = null;
      if (r.inventor) {
        inventors = Array.isArray(r.inventor) ? r.inventor : [r.inventor];
      }
      const assignee = r.assignee || null;
      const sourceUrl = r.pdf || (patentNumber ? `https://patents.google.com/patent/${patentNumber}/en` : r.patent_link);

      allExtracted.push({
        engine: 'google_patents',
        title: (r.title || '').trim(),
        url: sourceUrl,
        normalizedUrl: normalizeUrl(sourceUrl),
        snippet: (r.snippet || '').trim(),
        displayedLink: null,
        publicationDate: r.publication_date || null,
        position: r.position || null,
        authors: inventors,
        publication: assignee ? `Assignee: ${assignee}` : null,
        citationCount: null,
        patentNumber: patentNumber,
        inventors: inventors,
        assignee: assignee,
        filingDate: r.filing_date || null,
        patentPublicationDate: r.publication_date || null,
        pdfUrl: r.pdf || null,
        fullDocumentUrl: sourceUrl,
        metadata: {
          patentId: r.patent_id || null,
          countryStatus: r.country_status || null
        }
      });
      engineBreakdown.google_patents++;
    }
  }
}

// Cross-engine deduplication
const normalizedMap = new Map();
for (const item of allExtracted) {
  if (!item.normalizedUrl) continue;
  const score = (item.snippet || '').length + (item.title || '').length + (item.publicationDate ? 30 : 0) + (item.pdfUrl ? 50 : 0) + (item.citationCount ? 40 : 0);
  if (!normalizedMap.has(item.normalizedUrl) || normalizedMap.get(item.normalizedUrl)._score < score) {
    item._score = score;
    normalizedMap.set(item.normalizedUrl, item);
  }
}

const finalSources = Array.from(normalizedMap.values()).map((item, idx) => {
  const sourceId = 'S' + String(idx + 1).padStart(3, '0');
  delete item._score;
  delete item.normalizedUrl;
  return {
    sourceId,
    ...item
  };
});

return [{
  json: {
    success: true,
    topic,
    selectedEngines,
    totalSources: finalSources.length,
    engineBreakdown,
    sources: finalSources,
    metadata: {
      searchParameters: {
        topic,
        country,
        language,
        engines: selectedEngines
      },
      engineErrors,
      processedAt: new Date().toISOString()
    },
    limitations: [
      'Search snippets, abstracts, and patent overviews are preliminary evidence.',
      'Full documents and PDFs have not necessarily been retrieved or verified.'
    ]
  }
}];

const raw = $input.first()?.json || {};
const errorMsg = typeof raw.error === 'string'
  ? raw.error
  : (raw.error?.message || raw.message || 'Validation Error: Invalid input parameters.');
const cleanMsg = errorMsg.replace(/\s*\[line\s+\d+\]$/, '').replace(/^Error:\s*/, '');

return [{
  json: {
    success: false,
    error: {
      code: 'INVALID_INPUT',
      message: cleanMsg,
      details: 'Topic must be a non-empty string between 3 and 250 characters. Country and language must be valid ISO codes. Supported engines: google, google_scholar, google_news, google_patents.'
    },
    limitations: [
      'Request rejected before external search execution.'
    ]
  }
}];
